import{_ as t,c as r,o as n,a2 as a}from"./chunks/framework.jqDK1qTK.js";const m=JSON.parse('{"title":"Project Steering","description":"","frontmatter":{"github_repo":"https://github.com/gardener/documentation","github_subdir":"website/community/steering","params":{"github_branch":"master"},"path_base_for_github_subdir":{"from":"content/community/steering/_index.md","to":"_index.md"},"title":"Project Steering","weight":20,"prev":false,"next":false},"headers":[],"relativePath":"community/steering/_index.md","filePath":"community/steering/_index.md","lastUpdated":null}'),o={name:"community/steering/_index.md"};function i(s,e,l,c,h,d){return n(),r("div",null,e[0]||(e[0]=[a('<h1 id="project-steering" tabindex="-1">Project Steering <a class="header-anchor" href="#project-steering" aria-label="Permalink to &quot;Project Steering&quot;">​</a></h1><p>This page describes how <strong>project-wide topics</strong> in Gardener are proposed, discussed, and decided via <strong>Gardener Enhancement Proposals (GEPs)</strong> in the context of the Gardener <a href="https://github.com/gardener/documentation/tree/master/website/community/steering/product" target="_blank" rel="noreferrer"><strong>Product Steering Committee (PSC)</strong></a> and <a href="https://github.com/gardener/documentation/tree/master/website/community/steering/technical" target="_blank" rel="noreferrer"><strong>Technical Steering Committee (TSC)</strong></a>.</p><p>GEPs are the canonical mechanism for proposals that meet the criteria for steering-level discussion. They live in the dedicated repository <a href="https://github.com/gardener/enhancements" target="_blank" rel="noreferrer"><code>gardener/enhancements</code></a>.</p><p>These meetings are essential governance bodies in the Gardener project:</p><ul><li><strong>Product Steering</strong>: Focuses on prioritization, vision, roadmap alignment, and cross-cutting concerns.</li><li><strong>Technical Steering</strong>: Focuses on architecture, technical direction, and design decisions.</li></ul><p>Each proposal discussed in a steering meeting is represented by a <strong>Gardener Enhancement Proposal (GEP)</strong>. A GEP provides sufficient context, motivation, and a concrete ask or decision request to facilitate informed and effective discussion during the respective steering meeting.</p><h3 id="🧑‍💼-product-steering" tabindex="-1">🧑‍💼 Product Steering <a class="header-anchor" href="#🧑‍💼-product-steering" aria-label="Permalink to &quot;🧑‍💼 Product Steering&quot;">​</a></h3><p>Product Steering provides strategic direction for major product increments. Product ideas can be submitted to the Product Steering Committee as <strong>Gardener Enhancement Proposals (GEPs)</strong>. The proposer must provide a brief document outlining the idea. Ideally, if applicable, a prototype should be included to demonstrate feasibility, but no full implementation or design document is expected (or desired) at this stage.</p><p>So, Gardener&#39;s Product Steering discusses topics at an early stage, before substantial efforts begin. It focuses on the &#39;Whether&#39;/&#39;Why&#39; question. In contrast, <a href="https://github.com/gardener/documentation/tree/master/website/community/steering/technical" target="_blank" rel="noreferrer">Gardener&#39;s Technical Steering</a> discusses topics at a later stage, when a design document has been crafted. It focuses on the &#39;How&#39; question, meaning the go/no-go decision has already been made in the Product Steering. A topic which has passed the Product Steering is typically a natural fit for a Technical Steering once the design process reaches a sufficient technical depth.</p><p>The committee will schedule a Product Steering meeting, where the proposer presents the GEP. Committee members, interested contributors, and affected sponsors will challenge and discuss the idea. This meeting will be recorded.</p><p>Following this, a private go/no-go decision meeting with the affected sponsors will take place. This second meeting will not be recorded, but the outcome will be documented in the GEP.</p><h4 id="why-do-we-need-it" tabindex="-1">Why Do We Need It? <a class="header-anchor" href="#why-do-we-need-it" aria-label="Permalink to &quot;Why Do We Need It?&quot;">​</a></h4><p>We aim to align sponsored development capacity with Gardener&#39;s strategic vision and priorities. Investments should deliver value either to Gardener&#39;s users and operators or to the project and its overall reach.</p><h4 id="who-is-on-the-product-steering-committee" tabindex="-1">Who is on The Product Steering Committee? <a class="header-anchor" href="#who-is-on-the-product-steering-committee" aria-label="Permalink to &quot;Who is on The Product Steering Committee?&quot;">​</a></h4><p>The committee is elected by the project&#39;s active contributing sponsors and consists of a small number of members (at least three). Currently, the committee members are:</p><ul><li><a href="https://github.com/scheererj" target="_blank" rel="noreferrer">Johannes Scheerer</a> (<a href="mailto:johannes.scheerer@sap.com" target="_blank" rel="noreferrer">Email</a> and <a href="https://gardener-cloud.slack.com/team/U048D8K0N65" target="_blank" rel="noreferrer">Slack</a>)</li><li><a href="https://github.com/rfranzke" target="_blank" rel="noreferrer">Rafael Franzke</a> (<a href="mailto:rafael.franzke@sap.com" target="_blank" rel="noreferrer">Email</a> and <a href="https://gardener-cloud.slack.com/team/UAQT84PK7" target="_blank" rel="noreferrer">Slack</a>)</li><li><a href="https://github.com/timebertt" target="_blank" rel="noreferrer">Tim Ebert</a> (<a href="mailto:tim.ebert@stackit.cloud" target="_blank" rel="noreferrer">Email</a> and <a href="https://gardener-cloud.slack.com/team/U03VASPK6TC" target="_blank" rel="noreferrer">Slack</a>)</li><li><a href="https://github.com/vlerenc" target="_blank" rel="noreferrer">Vedran Lerenc</a> (<a href="mailto:vedran.lerenc@sap.com" target="_blank" rel="noreferrer">Email</a> and <a href="https://gardener-cloud.slack.com/team/UAQ7R439P" target="_blank" rel="noreferrer">Slack</a>)</li></ul><h4 id="key-considerations-for-topics" tabindex="-1">Key Considerations for Topics <a class="header-anchor" href="#key-considerations-for-topics" aria-label="Permalink to &quot;Key Considerations for Topics&quot;">​</a></h4><p>A topic qualifies for Product Steering if it:</p><ul><li>Requires <strong>significant development effort</strong> (≥ 6 or more person-months of work, calculated as full-time effort), OR</li><li>Has <strong>relevant cross-team impact</strong>, i.e., directly affects multiple teams (e.g., at least two distinct teams such as development, operations, or support) by altering workflows, system stability (like landscape integrity), or operational processes in a way that demands measurable adaptation or coordination, OR</li><li><strong>Impacts Gardener&#39;s users or ecosystem significantly</strong>, e.g., through changes to core functionality or interfaces, or <strong>significantly expands the project’s reach</strong> (e.g., enabling a new major use case or market), OR</li><li>Introduces <strong>high technical or operational risk</strong> - such as potential downtimes, data loss, or security vulnerabilities - that require formal evaluation and mitigation planning beyond routine testing.</li></ul><h3 id="🧑‍💻-technical-steering" tabindex="-1">🧑‍💻 Technical Steering <a class="header-anchor" href="#🧑‍💻-technical-steering" aria-label="Permalink to &quot;🧑‍💻 Technical Steering&quot;">​</a></h3><p>Technical Steering provides architectural and technical direction for major product increments. Technical documents can be submitted to the Technical Steering Committee as <strong>Gardener Enhancement Proposals (GEPs)</strong>. The document should outline the proposed solution, with a particular focus on APIs and interfaces, while also covering other relevant aspects, but no full implementation is expected (or desired) at this stage.</p><p>So, Gardener&#39;s Technical Steering discusses topics at a later stage, when a design document has been crafted. It focuses on the &#39;How&#39; question, meaning the go/no-go decision has already been made. In contrast, <a href="https://github.com/gardener/documentation/tree/master/website/community/steering/product" target="_blank" rel="noreferrer">Gardener&#39;s Product Steering</a> discusses topics at an early stage, before substantial efforts begin. It focuses on the &#39;Whether&#39;/&#39;Why&#39; question.</p><p>The committee will schedule a Technical Steering meeting where the proposer presents the GEP. Committee members and interested contributors will challenge and discuss the idea. This meeting will be recorded.</p><p>A decision on how to proceed with the proposal, including any recommended improvements, will be made within the same meeting. The decision and any required changes will be documented in the GEP.</p><h4 id="why-do-we-need-it-1" tabindex="-1">Why Do We Need It? <a class="header-anchor" href="#why-do-we-need-it-1" aria-label="Permalink to &quot;Why Do We Need It?&quot;">​</a></h4><p>Technical Steering ensures that major technical changes align with Gardener&#39;s architectural principles and long-term sustainability. It prevents fragmentation and promotes consistency in the project&#39;s evolution. The process helps ensure that major technical investments deliver value to both Gardener&#39;s users and maintainers.</p><h4 id="who-is-on-the-technical-steering-committee" tabindex="-1">Who is on The Technical Steering Committee? <a class="header-anchor" href="#who-is-on-the-technical-steering-committee" aria-label="Permalink to &quot;Who is on The Technical Steering Committee?&quot;">​</a></h4><p>The committee is elected by the project&#39;s active code owners and contributors and consists of a small number of members (at least three). Currently, the committee members are:</p><ul><li><a href="https://github.com/scheererj" target="_blank" rel="noreferrer">Johannes Scheerer</a> (<a href="mailto:johannes.scheerer@sap.com" target="_blank" rel="noreferrer">Email</a> and <a href="https://gardener-cloud.slack.com/team/U048D8K0N65" target="_blank" rel="noreferrer">Slack</a>)</li><li><a href="https://github.com/rfranzke" target="_blank" rel="noreferrer">Rafael Franzke</a> (<a href="mailto:rafael.franzke@sap.com" target="_blank" rel="noreferrer">Email</a> and <a href="https://gardener-cloud.slack.com/team/UAQT84PK7" target="_blank" rel="noreferrer">Slack</a>)</li><li><a href="https://github.com/timebertt" target="_blank" rel="noreferrer">Tim Ebert</a> (<a href="mailto:tim.ebert@stackit.cloud" target="_blank" rel="noreferrer">Email</a> and <a href="https://gardener-cloud.slack.com/team/U03VASPK6TC" target="_blank" rel="noreferrer">Slack</a>)</li><li><a href="https://github.com/vlerenc" target="_blank" rel="noreferrer">Vedran Lerenc</a> (<a href="mailto:vedran.lerenc@sap.com" target="_blank" rel="noreferrer">Email</a> and <a href="https://gardener-cloud.slack.com/team/UAQ7R439P" target="_blank" rel="noreferrer">Slack</a>)</li></ul><h4 id="key-considerations-for-topics-1" tabindex="-1">Key Considerations for Topics <a class="header-anchor" href="#key-considerations-for-topics-1" aria-label="Permalink to &quot;Key Considerations for Topics&quot;">​</a></h4><p>A topic qualifies for Technical Steering if it:</p><ul><li>Requires <strong>significant development effort</strong>, OR</li><li>Has <strong>relevant cross-team impact</strong>, OR</li><li><strong>Impacts Gardener&#39;s users or ecosystem significantly</strong>, OR</li><li>Introduces <strong>high technical or operational risk</strong></li></ul><h3 id="🧭-how-to-propose-a-topic" tabindex="-1">🧭 <a href="https://github.com/gardener/enhancements/blob/main/README.md#-how-to-propose-a-gardener-enhancement" target="_blank" rel="noreferrer">How to Propose a Topic</a> <a class="header-anchor" href="#🧭-how-to-propose-a-topic" aria-label="Permalink to &quot;🧭 [How to Propose a Topic](https://github.com/gardener/enhancements/blob/main/README.md#-how-to-propose-a-gardener-enhancement)&quot;">​</a></h3><p>If you&#39;d like to bring a topic to either steering meeting, follow these steps:</p><ol><li><strong>Choose the relevant committee</strong>: Product or Technical.</li><li><strong>Create a tracking issue to reserve a GEP number</strong>: <a href="https://github.com/gardener/enhancements/issues/new?template=enhancement.md" target="_blank" rel="noreferrer">https://github.com/gardener/enhancements/issues/new?template=enhancement.md</a></li><li><strong>Create a proposal document</strong> using the <a href="https://github.com/gardener/enhancements/tree/master/geps/NNNN-gep-template" target="_blank" rel="noreferrer">official template</a> in <a href="https://github.com/gardener/enhancements" target="_blank" rel="noreferrer"><code>gardener/enhancements</code></a>.</li><li><strong>Open a Pull Request</strong> against the <code>gardener/enhancements</code> repository.</li><li>A member of the relevant steering committee will coordinate review and scheduling.</li></ol><blockquote><p>💡 Keep your proposal concise (2–5 pages). The goal is to clearly motivate your idea and define what decision or feedback you need.</p></blockquote><h4 id="📆-what-happens-after-opening-a-pr" tabindex="-1">📆 What Happens After Opening a PR? <a class="header-anchor" href="#📆-what-happens-after-opening-a-pr" aria-label="Permalink to &quot;📆 What Happens After Opening a PR?&quot;">​</a></h4><p>Once your PR is open:</p><ul><li>A <strong>member of the relevant steering committee</strong> will reach out and coordinate the next steps.</li><li>The proposal is first <strong>reviewed asynchronously</strong> by the committee via the Pull Request: <ul><li>Steering committee members review the document and leave questions or comments <strong>directly in the PR review</strong>.</li><li>The goal of this phase is to clarify open questions and address smaller issues before the meeting.</li></ul></li><li>Once feedback from a <strong>majority of the committee</strong> (typically 3 out of 4 members) has been provided, a steering meeting is scheduled. <ul><li>A <a href="/community/steering/#-meeting-process">PSC/TSC meeting</a> is usually scheduled <strong>about two weeks later</strong> to allow for review ping-pong and for incorporating feedback into the document.</li></ul></li><li>The meeting will be <strong>announced</strong> to the community via our <a href="https://gardener-cloud.slack.com/archives/C045DSWJZB9" target="_blank" rel="noreferrer"><code>#gardener</code></a> Slack channel and in the public meeting agenda (e.g., <a href="https://github.com/gardener/documentation/tree/master/website/community/steering/product" target="_blank" rel="noreferrer">here</a> or <a href="https://github.com/gardener/documentation/tree/master/website/community/steering/technical" target="_blank" rel="noreferrer">here</a>).</li><li>Based on the outcome of the meeting, the proposal in the GEP PR may need to be <strong>adjusted, refined, or extended</strong>. In this case, the PR remains open and meeting feedback is addressed asynchronously. Depending on the outcome, <strong>an additional steering meeting may be scheduled</strong>. Once all steering committee members are satisfied, the GEP PR is merged, which signals a clear <strong>go for the next steps</strong> (typically implementation work).</li></ul><h3 id="🗣️-participation" tabindex="-1">🗣️ Participation <a class="header-anchor" href="#🗣️-participation" aria-label="Permalink to &quot;🗣️ Participation&quot;">​</a></h3><ul><li>Those who wish to <strong>actively challenge or discuss</strong> the proposal can <strong>request an invitation</strong> from any committee member.</li><li>Others are encouraged to <strong>watch the recording</strong> instead of attending live.</li></ul><h3 id="📑-meeting-process" tabindex="-1">📑 Meeting Process <a class="header-anchor" href="#📑-meeting-process" aria-label="Permalink to &quot;📑 Meeting Process&quot;">​</a></h3><ul><li>Attendees are expected to have <strong>read the proposal in advance and come prepared</strong>.</li><li>Product Steering: <ul><li>The meeting will be <strong>scheduled for 1h</strong> and is split into <strong>30-30</strong> minute blocks: <ul><li>Attendees then have up to <strong>30 minutes</strong> time to <strong>ask clarifying questions</strong>.</li><li>The last <strong>30 minutes</strong> are reserved to <strong>provide feedback, possibly challenge the document, and generally for an active discussion</strong>.</li></ul></li></ul></li><li>Technical Steering: <ul><li>The meeting will be <strong>scheduled for 1h</strong> and is split into <strong>25-25-10</strong> minute blocks: <ul><li>Attendees then have up to <strong>25 minutes</strong> time to <strong>ask clarifying questions</strong>.</li><li>The next <strong>25 minutes</strong> are reserved to <strong>provide feedback, possibly challenge the document, and generally for an active discussion</strong>.</li><li>The last <strong>10 minutes</strong> are reserved to <strong>take a decision</strong>.</li></ul></li></ul></li><li>The session is <strong>recorded and shared</strong> with the community for transparency.</li></ul><h3 id="👨‍⚖️-decision-process" tabindex="-1">👨‍⚖️ Decision Process <a class="header-anchor" href="#👨‍⚖️-decision-process" aria-label="Permalink to &quot;👨‍⚖️ Decision Process&quot;">​</a></h3><ul><li>Product Steering: <ul><li>A <strong>private meeting</strong> with sponsors follows to make a <strong>go/no-go decision</strong>.</li><li>The final decision is <strong>documented on this community page</strong>.</li></ul></li><li>Technical Steering: <ul><li>A <strong>go/no-go decision</strong> is made <strong>during the meeting</strong>, along with recommended improvements if needed.</li><li>The final decision and any necessary changes are <strong>documented on this community page</strong>.</li></ul></li></ul><h3 id="🗒️-where-are-decisions-and-meeting-minutes-published" tabindex="-1">🗒️ Where Are Decisions and Meeting Minutes Published? <a class="header-anchor" href="#🗒️-where-are-decisions-and-meeting-minutes-published" aria-label="Permalink to &quot;🗒️ Where Are Decisions and Meeting Minutes Published?&quot;">​</a></h3><p>A link to the <strong>recording</strong>, the final <strong>decisions</strong> and (optionally) <strong>meeting minutes</strong> will be tracked directly in the top of the proposal documents.</p>',47)]))}const u=t(o,[["render",i]]);export{m as __pageData,u as default};
